from itertools import product

def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

n = 7
solutions = []
# The sum of all x[i] must be n
# Each x[i] is between 0 and n
# We can prune: sum(seq) must equal n
for seq in product(range(n+1), repeat=n):
    if sum(seq) != n:
        continue
    if is_magic(seq):
        solutions.append(seq)
        print(f"Found: {seq}")

print(f"Total solutions: {len(solutions)}")
